#include "lin_master.h"
#include "lin_sim.h"
#include <string.h>
void lin_master_init(lin_master_t*m,uint32_t timeout){if(!m)return;memset(m,0,sizeof(*m));m->timeout_us=timeout;lin_schedule_init(&m->schedule);}
lin_status_t lin_master_add_slave(lin_master_t*m,lin_slave_t s){if(!m)return LIN_ERR_ARGUMENT;if(m->slave_count>=LIN_MAX_SLAVES)return LIN_ERR_CAPACITY;m->slaves[m->slave_count++]=s;return LIN_OK;}
lin_status_t lin_master_add_slot(lin_master_t*m,lin_schedule_slot_t s){if(!m)return LIN_ERR_ARGUMENT;if(s.type==LIN_SLOT_DIAGNOSTIC){if(s.frame_id!=0x3C&&s.frame_id!=0x3D)return LIN_ERR_ARGUMENT;}else if(s.slave_index>=LIN_MAX_SLAVES)return LIN_ERR_ARGUMENT;return lin_schedule_add(&m->schedule,s);}
lin_status_t lin_master_tick(lin_master_t*m,lin_frame_t*tx,lin_frame_t*rx,bool*received){if(!m||!tx||!rx||!received)return LIN_ERR_ARGUMENT;const lin_schedule_slot_t*slot=lin_schedule_current(&m->schedule);if(!slot)return LIN_ERR_NO_SLOT;m->now_us+=(uint64_t)slot->delay_ms*1000ULL;uint8_t cmd[LIN_MAX_DATA]={0};lin_status_t st;if(slot->type==LIN_SLOT_DIAGNOSTIC){cmd[0]=0x03;cmd[1]=0x22;cmd[2]=0xF1;cmd[3]=0x90;st=lin_encode_frame(tx,slot->frame_id,cmd,4,false);m->stats.diagnostic_requests++;}else st=lin_encode_frame(tx,slot->frame_id,cmd,0,true);if(st!=LIN_OK)return st;tx->timestamp_us=m->now_us;m->stats.frames_sent++;*received=false;
if(slot->type==LIN_SLOT_DIAGNOSTIC){st=LIN_OK;}else if(slot->slave_index<m->slave_count){lin_slave_t*s=&m->slaves[slot->slave_index];lin_sim_respond(s,tx,rx,received,m->now_us);if(*received){if(rx->timestamp_us<m->now_us||rx->timestamp_us-m->now_us>m->timeout_us){*received=false;m->stats.timeouts++;st=LIN_ERR_TIMEOUT;}else{st=lin_validate_frame(rx,true);if(st==LIN_OK){if(rx->dlc!=slot->expected_dlc){m->stats.checksum_errors++;st=LIN_ERR_CHECKSUM;}else m->stats.frames_received++;}else if(st==LIN_ERR_CHECKSUM)m->stats.checksum_errors++;else if(st==LIN_ERR_PID)m->stats.pid_errors++;}}else{m->stats.timeouts++;st=LIN_ERR_TIMEOUT;}}else{m->stats.timeouts++;st=LIN_ERR_TIMEOUT;}
if(st==LIN_ERR_TIMEOUT)m->stats.recovered_slots++;lin_schedule_advance(&m->schedule,m->now_us);return st;}
lin_status_t lin_master_diagnostic_request(lin_master_t*m,uint8_t idx,uint8_t service,const uint8_t*d,uint8_t n,lin_frame_t*tx){if(!m||!tx||idx>=m->slave_count||n>5||(!d&&n))return LIN_ERR_ARGUMENT;uint8_t p[LIN_MAX_DATA]={0};p[0]=(uint8_t)(1u+n);p[1]=service;for(uint8_t i=0;i<n;i++)p[2+i]=d[i];m->stats.diagnostic_requests++;return lin_encode_frame(tx,0x3C,p,(uint8_t)(2+n),false);}
